#!/bin/bash
# Detached, checkpointed fix1 pipeline (CSO QA on the page pass). Steps write $O/steps_fix1/<n>.ok; rerun skips done steps.
H=/workspace/harvest-2026-10-30; P=$H/pp3; O=$H/out_pagepass; W=/workspace/wt-pp; S=$O/steps_fix1; X=$O/fix1; mkdir -p $S $X; cd $H
log(){ echo "$(date +%T) $*"; }
ck(){ echo "- $(date '+%Y-%m-%d %H:%M') PDT pagepass fix1: $*" >> $H/summary.md; }
step(){ [ -f $S/$1.ok ] && { log "skip $1"; return 0; }; log "start $1"; if eval "$2"; then touch $S/$1.ok; log "ok $1"; else log "FAIL $1"; ck "step $1 FAILED (see $O/run_fix1.log)"; exit 1; fi; }
# 1 wait for the Nov 1 fetch, then one resumable retry pass for errors (never a bot-walled host)
step 01_fetch 'while pgrep -f "pp3/tools/fetch.py|\.\./tools/fetch.py targets" >/dev/null; do sleep 30; done; cd $P/fetch && PP_DIR=$PWD PP_INFLIGHT=1 PP_DELAY=1.6 python3 ../tools/fetch.py targets.ndjson >> fetch.log 2>&1; cd $H; ck "Nov 1 fetch done: $(python3 -c "import json,collections as C;R={};[R.__setitem__(json.loads(l)[\"key\"],json.loads(l)) for l in open(\"$P/fetch/results.ndjson\")];print(dict(C.Counter((r[\"host\"],r.get(\"result\"),r.get(\"http\")) for r in R.values())))")"'
# 2 page pass re-applied from main with the fix-4 store rule
step 02_apply 'python3 $P/tools/apply_pp2.py $O/base_main_e1a3cb4.snapshot.json.gz $X/pagepass.snapshot.json.gz $X > $X/apply_stdout.json'
# 3 fixes 1-3
step 03_fix1 'python3 $P/tools/fix1.py $X/pagepass.snapshot.json.gz $X/inventory.snapshot.json.gz $X > $X/fix1_stdout.json && ck "fix1 applied: $(python3 -c "import json;d=json.load(open(\"$X/fix1_summary.json\"));print(d[\"in\"],\"->\",d[\"out\"],d[\"removedOrHeldByReason\"],d[\"typeChanges\"])")"'
step 04_windows 'B=$(python3 -c "import json;print(json.load(open(\"$X/fix1_summary.json\"))[\"builtAt\"])") && python3 $H/windows.py $X/inventory.snapshot.json.gz $X/windows.json >/dev/null && BUILT=$B python3 $H/pp2/tools/windows_at.py $O/base_main_e1a3cb4.snapshot.json.gz $X/windows_base_at_fix1_builtAt.json >/dev/null && ck "windows: $(python3 -c "import json;d=json.load(open(\"$X/windows.json\"));print(\"builtAt\",d[\"builtAt\"],\"loaded\",d[\"loaded\"],\"14d\",d[\"windows\"][\"14\"][\"eligible\"],\"30d\",d[\"windows\"][\"30\"][\"eligible\"])")"'
step 05_qa 'cp $X/pagepass_stores_created.csv $X/ 2>/dev/null; python3 $P/tools/qa_fix1.py $O/base_main_e1a3cb4.snapshot.json.gz $X/inventory.snapshot.json.gz $X > $X/qa.txt && cp $X/qa_sample_30_pagepass_fix1.csv $O/qa_sample_30_pagepass_fix1.csv'
step 06_coords 'cp $X/inventory.snapshot.json.gz $W/lib/agent-core/data/inventory.snapshot.json.gz && cd $W/lib/agent-core && npx tsx scripts/build-dealer-city-coords.ts /workspace/gaz/2023_Gaz_place_national.txt /workspace/gaz/2023_Gaz_cousubs_national.txt > $X/coords.txt 2>&1; r=$?; cd $H; tail -3 $X/coords.txt; test $r -eq 0'
step 07_commit 'cd $W && cp $P/tools/{apply_pp2.py,fix1.py,parse_ia.py,qa_fix1.py,run_fix1.sh} lib/agent-core/scripts/pagepass-2026-11-01/ && cp $P/tools/fetch.py lib/agent-core/scripts/pagepass-2026-11-01/fetch_nov1.py && python3 -c "import json;d={\"pagepass\":json.load(open(\"$X/pagepass_apply_summary.json\")),\"fix1\":json.load(open(\"$X/fix1_summary.json\")),\"windows\":json.load(open(\"$X/windows.json\"))};json.dump(d,open(\"lib/agent-core/data/pagepass-2026-11-01.stats.json\",\"w\"),indent=1)" && git add lib/agent-core/data/inventory.snapshot.json.gz lib/agent-core/data/pagepass-2026-11-01.stats.json lib/agent-core/src/dealer-city-coords.ts lib/agent-core/scripts/pagepass-2026-11-01 && git commit -q -F $X/commit_msg.txt && git rev-parse --short HEAD > $X/commit.txt && cd $H && ck "local commit $(cat $X/commit.txt) on data/pagepass-2026-11-01 (not pushed)"'
step 08_test_core 'cd $W/lib/agent-core && timeout 1500 npx vitest run --maxWorkers=2 --minWorkers=1 > $X/test_agent_core.txt 2>&1; cd $H; tail -6 $X/test_agent_core.txt; true'
step 09_test_api 'cd $W/artifacts/api-server && timeout 2400 npx vitest run --maxWorkers=2 --minWorkers=1 > $X/test_api.txt 2>&1; cd $H; tail -6 $X/test_api.txt; true'
step 10_test_web 'cd $W/artifacts/rv-marketplace && timeout 1200 npx vitest run --maxWorkers=2 --minWorkers=1 > $X/test_web.txt 2>&1; cd $H; tail -6 $X/test_web.txt; true'
step 11_mem 'cp /workspace/harvest-2026-10-31/mem/_mem_new.ts $W/artifacts/api-server/_mem_new.ts && cd $W/artifacts/api-server && (NODE_OPTIONS=--expose-gc npx tsx _mem_new.ts > $X/mem.json 2>&1; rm -f _mem_new.ts) && cd $H && tail -1 $X/mem.json'
step 12_bundle 'python3 $P/tools/bundle_fix1.py && ck "tests/mem/bundle done: $(cat $X/result_line.txt)"'
log "ALL DONE"; touch $X/PIPELINE_DONE
